using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using TasiaCraft;
public static partial class MediaBinTest {
 static List<Clip> Selected(Editor e){return (List<Clip>)Call(e,"SelectedClips");}
 static void ChooseBin(Editor e,params string[] ids){var b=(ListBox)Field(e,"bin");b.SelectedItems.Clear();foreach(var i in b.Items.OfType<ListBoxItem>().Where(i=>i.Tag is Media&&ids.Contains(((Media)i.Tag).Id)))i.IsSelected=true;}
 static string[] BinIds(Editor e){return ((ListBox)Field(e,"bin")).SelectedItems.OfType<ListBoxItem>().Where(i=>i.Tag is Media).Select(i=>((Media)i.Tag).Id).OrderBy(x=>x).ToArray();}
 static MenuItem LocateBinMenu(Editor e){return ((ListBox)Field(e,"bin")).ContextMenu.Items.OfType<MenuItem>().First(i=>(string)i.Header=="Select on Timeline");}
 static void NavigationTests(Editor editor,Project original,LivePreview preview){
  var p=Clone(original);p.Clips.Clear();p.Groups.Clear();p.HiddenTracks.Clear();p.LockedTracks.Clear();p.TrackCount=4;
  var a=new Clip{MediaId=p.Media[0].Id,Duration=1,Track=0};var b=new Clip{MediaId=p.Media[2].Id,Duration=1,Track=1};var later=new Clip{MediaId=p.Media[0].Id,Start=6,Duration=1,Track=2};var text=new Clip{Text="Navigation test",Duration=1,Track=3};p.Clips.AddRange(new[]{a,b,later,text});p.Groups.Add(new ClipGroup{Name="Mixed sources",ClipIds=new List<string>{a.Id,b.Id}});p.LockedTracks.Add(1);p.HiddenTracks.Add(2);
  var video=Engine.Probe(Path.Combine(root,"source-preview.mp4"));p.Media.Add(video);p.Clips.Add(new Clip{MediaId=video.Id,Stream="audio",Start=1,Duration=.5,Track=1});p.Clips.Add(new Clip{MediaId=video.Id,Stream="video",Start=1,Duration=.5,Track=0});Engine.Validate(p,true);
  string baseline=json.Serialize(p);var pixels=Preview(preview,p);var output=Export(p,"navigation-before");
  var matches=MediaBinOperations.TimelineReferences(p,new[]{p.Media[0],p.Media[0]});Check(matches.Select(c=>c.Id).SequenceEqual(new[]{a.Id,later.Id}),"timeline lookup returns distinct references in project order including hidden tracks");Check(MediaBinOperations.TimelineReferences(p,new[]{p.Media[1]}).Count==0,"alias source paths do not conflate distinct media IDs");Check(MediaBinOperations.TimelineReferences(p,new[]{video}).Count==2,"separated audio and video references both located");Check(MediaBinOperations.TimelineReferences(p,new[]{new Media{Id=p.Media[0].Id,Path=p.Media[0].Path}}).Count==0,"stale media object with same ID rejected");Check(MediaBinOperations.SourceReferences(p,new[]{a,later,text}).Single()==p.Media[0],"reverse lookup deduplicates source and ignores text");Check(MediaBinOperations.SourceReferences(p,new[]{new Clip{Id=a.Id,MediaId=a.MediaId}}).Count==0,"reverse lookup rejects stale clips");Check(MediaBinOperations.SourceReferences(p,p.Clips).Count==3,"reverse lookup returns only referenced media");bool invalid=false;try{MediaBinOperations.TimelineReferences(null,new Media[0]);}catch(ArgumentException){invalid=true;}Check(invalid,"null project navigation rejected");invalid=false;try{MediaBinOperations.SourceReferences(p,null);}catch(ArgumentException){invalid=true;}Check(invalid,"null reverse selection rejected");Check(json.Serialize(p)==baseline,"pure navigation leaves project metadata untouched");
  Reset(editor,p);Call(editor,"Panel","Media");var current=P(editor);Call(editor,"Seek",.5);double head=(double)Field(editor,"head");Set(editor,"openedGroupId",current.Groups[0].Id);ChooseBin(editor,current.Media[0].Id);LocateBinMenu(editor).RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));Check(Field(editor,"openedGroupId")==null,"Select on Timeline returns to Main Timeline");Check(Selected(editor).Select(c=>c.Id).OrderBy(x=>x).SequenceEqual(new[]{a.Id,b.Id,later.Id}.OrderBy(x=>x)),"actual context command selects every match and whole root group units");Check(Selected(editor).Any(c=>c.Track==1)&&Selected(editor).Any(c=>c.Track==2),"locked group members and hidden track matches are selected");Check((double)Field(editor,"head")==head,"navigation preserves timeline playhead");Check(json.Serialize(current)==baseline&&Undos(editor)==0&&!(bool)Field(editor,"dirty"),"timeline lookup changes no project dirty or undo state");Call(editor,"DeleteSelection");Check(json.Serialize(current)==baseline&&Undos(editor)==0,"navigation selection retains locked-track edit guards");
  var savedIds=Selected(editor).Select(c=>c.Id).ToArray();ChooseBin(editor,current.Media[1].Id);Call(editor,"SelectBinOnTimeline");Check(Selected(editor).Select(c=>c.Id).SequenceEqual(savedIds),"unused-only lookup preserves timeline selection");ChooseBin(editor);Call(editor,"SelectBinOnTimeline");Check(Selected(editor).Select(c=>c.Id).SequenceEqual(savedIds),"empty bin lookup preserves timeline selection");ChooseBin(editor,video.Id);Set(editor,"busy",true);Call(editor,"SelectBinOnTimeline");Check(Selected(editor).Select(c=>c.Id).SequenceEqual(savedIds),"busy timeline lookup preserves selection");Set(editor,"busy",false);Call(editor,"SelectBinOnTimeline");Check(Selected(editor).Count==2&&Selected(editor).All(c=>c.MediaId==video.Id),"actual lookup selects both separated stream halves");ChooseBin(editor,current.Media[0].Id,video.Id);Call(editor,"SelectBinOnTimeline");Check(Selected(editor).Count==5,"multiple bin entries form a union with group completion");
  Call(editor,"SetSelected",new object[]{new[]{current.Clips.First(c=>c.Id==later.Id)}});Set(editor,"zoom",220.0);Call(editor,"DrawTimeline");var canvas=(Canvas)Field(editor,"timeline");var scroller=Tree(editor).OfType<ScrollViewer>().First(s=>s.Content==canvas);scroller.ScrollToHorizontalOffset(0);ChooseBin(editor,current.Media[0].Id);current.Groups.Clear(); // Temporarily remove the group to make the first match distant.
  var only=current.Clips.First(c=>c.Id==a.Id);only.MediaId=current.Media[1].Id;Call(editor,"SelectBinOnTimeline");editor.UpdateLayout();Check(Selected(editor).Single().Id==later.Id,"distant hidden clip remains a valid navigation target");Check(scroller.HorizontalOffset>0,"Select on Timeline scrolls to distant result without seeking");only.MediaId=current.Media[0].Id;current.Groups=Clone(p).Groups;Set(editor,"zoom",35.0);Call(editor,"DrawTimeline");
  Set(editor,"mediaSort","Name");Set(editor,"mediaDescending",true);Set(editor,"mediaTiles",false);Set(editor,"mediaFilter","Audio");Call(editor,"Panel","Media");Call(editor,"SetSelected",new object[]{new[]{current.Clips.First(c=>c.Id==a.Id),current.Clips.First(c=>c.Id==later.Id),current.Clips.First(c=>c.Id==text.Id)}});Call(editor,"Panel","Annotations");Call(editor,"SelectTimelineInBin");Check((string)Field(editor,"activePanel")=="Media"&&(string)Field(editor,"mediaFilter")=="All media","reverse navigation reveals Media tool and clears type filter");Check(BinIds(editor).SequenceEqual(new[]{current.Media[0].Id}),"reverse navigation deduplicates shared sources and ignores text");Check((string)Field(editor,"mediaSort")=="Name"&&(bool)Field(editor,"mediaDescending")&&!(bool)Field(editor,"mediaTiles"),"reverse navigation preserves sort direction and layout");Check(Selected(editor).Count==3&&(double)Field(editor,"head")==head,"reverse lookup preserves timeline selection and head");
  Call(editor,"SetSelected",new object[]{current.Clips.Where(c=>c.MediaId==video.Id).ToArray()});Call(editor,"SelectTimelineInBin");Check(BinIds(editor).SequenceEqual(new[]{video.Id}),"reverse lookup maps separated halves to one media entry");var previousBin=BinIds(editor);Call(editor,"SetSelected",new object[]{new[]{current.Clips.First(c=>c.Id==text.Id)}});Set(editor,"mediaFilter","Video");Call(editor,"Panel","Media");Call(editor,"SelectTimelineInBin");Check((string)Field(editor,"mediaFilter")=="Video"&&BinIds(editor).SequenceEqual(previousBin),"text-only reverse lookup preserves current bin view and selection");Call(editor,"SetSelected",new object[]{new[]{current.Clips.First(c=>c.Id==a.Id)}});Set(editor,"busy",true);Call(editor,"SelectTimelineInBin");Check(BinIds(editor).SequenceEqual(previousBin)&&(string)Field(editor,"mediaFilter")=="Video","busy reverse lookup preserves bin state");Set(editor,"busy",false);
  Call(editor,"DrawTimeline");var box=((Canvas)Field(editor,"timeline")).Children.OfType<Border>().First(x=>x.ContextMenu!=null&&x.ContextMenu.Items.OfType<MenuItem>().Any(i=>(string)i.Header=="Select in Media Bin"));var reverse=box.ContextMenu.Items.OfType<MenuItem>().First(i=>(string)i.Header=="Select in Media Bin");reverse.RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));Check(BinIds(editor).SequenceEqual(new[]{current.Media[0].Id}),"actual timeline context command selects the current source in bin");
  var live=(LivePreview)Field(editor,"live");live.Play();ChooseBin(editor,current.Media[0].Id);Call(editor,"SelectBinOnTimeline");Check(live.IsPlaying,"Select on Timeline preserves active canvas playback");Call(editor,"SelectTimelineInBin");Check(live.IsPlaying,"Select in Media Bin preserves active canvas playback");live.Pause();var redo=(Stack<string>)Field(editor,"redo");redo.Push("navigation-redo-sentinel");ChooseBin(editor,video.Id);Call(editor,"SelectBinOnTimeline");Call(editor,"SelectTimelineInBin");Check(redo.Count==1&&redo.Peek()=="navigation-redo-sentinel","navigation preserves redo history");redo.Clear();
  string path=current.Media[0].Path;current.Media[0].Path=Path.Combine(root,"missing-navigation.png");ChooseBin(editor,current.Media[0].Id);Call(editor,"SelectBinOnTimeline");Check(Selected(editor).Count==3,"navigation uses references even when a source file is missing");current.Media[0].Path=path;Check(json.Serialize(current)==baseline&&Undos(editor)==0&&!(bool)Field(editor,"dirty"),"bidirectional navigation leaves complete project and undo state intact");Check(Preview(preview,current).SequenceEqual(pixels)&&Export(current,"navigation-after").SequenceEqual(output),"navigation preserves main preview and decoded export pixels");string file=Path.Combine(root,"navigation.tasiaproj");Engine.Save(current,file);Check(json.Serialize(Engine.Load(file))==baseline,"navigation preserves exact save and reopen data");
  Set(editor,"mediaSort","Type");Set(editor,"mediaDescending",false);Set(editor,"mediaTiles",true);Set(editor,"mediaFilter","All media");Reset(editor,original);
 }
}
